<?php
require __DIR__ . '/../layouts/header.php';
$tribunalRule = $detail && (int) $detail['requiere_tribunal'] === 1;
$defenseRule = $detail && (int) $detail['requiere_defensa'] === 1;
$latestDefense = null;
foreach (($detail['defensas'] ?? []) as $defense) {
    if ($defense['estado'] !== 'cancelada') { $latestDefense = $defense; break; }
}
$attemptsUsed = $detail ? count(array_filter($detail['defensas'], static fn (array $defense): bool => $defense['estado'] !== 'cancelada')) : 0;
$maxReached = $detail && $detail['max_defensas'] !== null && $attemptsUsed >= (int) $detail['max_defensas'];
$observedAtLimit = $latestDefense && $latestDefense['estado'] === 'realizada'
    && $latestDefense['resultado'] === 'observado' && $maxReached;
$terminalDefense = $latestDefense && $latestDefense['estado'] === 'realizada'
    && (in_array($latestDefense['resultado'], ['aprobado', 'reprobado'], true) || $observedAtLimit);
$canClose = $detail && $detail['estado'] === 'activo' && $allReady && (!$defenseRule || $terminalDefense);
$tribunalPresident = null;
$tribunalMemberIds = [];
foreach (($detail['tribunal_miembros'] ?? []) as $member) {
    if ($member['rol'] === 'presidente') { $tribunalPresident = (int) $member['id_usuario']; }
    else { $tribunalMemberIds[] = (int) $member['id_usuario']; }
}
$maxDefenses = $detail ? $detail['max_defensas'] : null;
?>
<main class="container mg-page">
    <div class="page-heading"><div><span class="hero-kicker">Administración MG</span><h1>Defensas y cierre</h1><p>Revisa el checklist de cada trabajo, conforma tribunales, programa intentos y registra el cierre final.</p></div><a class="btn btn-outline-secondary" href="<?= e(app_url('modalidades-grado/')) ?>">Volver al resumen</a></div>
    <?php if ($message): ?><p class="success" role="status"><?= e($message) ?></p><?php endif; ?>
